 17→pub(crate) const DEFAULT_WIDTH: u16 = 80;
 18→
 19→#[inline]
 20→pub(crate) fn is_a_terminal(out: &impl AsRawFd) -> bool {
 21→    unsafe { libc::isatty(out.as_raw_fd()) != 0 }
 22→}
 23→
 24→pub(crate) fn is_a_color_terminal(out: &Term) -> bool {
 25→    if !is_a_terminal(out) {
 26→        return false;
 27→    }
 28→
 29→    if env::var("NO_COLOR").is_ok() {
 30→        return false;
 31→    }
 32→
 33→    match env::var("TERM") {
 34→        Ok(term) => term != "dumb",
 35→        Err(_) => false,
 36→    }
 37→}
 38→
 39→pub(crate) fn is_a_true_color_terminal(out: &Term) -> bool {
 40→    if !is_a_color_terminal(out) {
 41→        return false;
 42→    }
 43→    env::var("COLORTERM").is_ok_and(|term| term == "truecolor" || term == "24bit")
 44→}
 45→
 46→fn c_result<F: FnOnce() -> libc::c_int>(f: F) -> io::Result<()> {
 47→    let res = f();
 48→    if res != 0 {
 49→        Err(io::Error::last_os_error())
 50→    } else {
 51→        Ok(())
 52→    }
 53→}
 54→
 55→pub(crate) fn terminal_size(out: &Term) -> Option<(u16, u16)> {
 56→    if !is_a_terminal(out) {
 57→        return None;
 58→    }
 59→    let winsize = unsafe {
 60→        let mut winsize: libc::winsize = mem::zeroed();
 61→
 62→        // FIXME: ".into()" used as a temporary fix for a libc bug
 63→        // https://github.com/rust-lang/libc/pull/704
 64→        #[allow(clippy::useless_conversion)]
 65→        libc::ioctl(out.as_raw_fd(), libc::TIOCGWINSZ.into(), &mut winsize);
 66→        winsize
 67→    };
 68→    if winsize.ws_row > 0 && winsize.ws_col > 0 {
 69→        Some((winsize.ws_row, winsize.ws_col))
 70→    } else {
 71→        None
 72→    }
 73→}
