fn is_eof_error(e: &BivvyError) -> bool {
    matches!(e, BivvyError::Io(io_err) if io_err.kind() == std::io::ErrorKind::UnexpectedEof)
}

/// Convert dialoguer errors to BivvyError.
///
/// EOF errors (from Ctrl+D) are converted to `UserCancelled`.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    let io_err: std::io::Error = e.into();
    if io_err.kind() == std::io::ErrorKind::UnexpectedEof {
        BivvyError::UserCancelled
    } else {
        BivvyError::Io(io_err)
    }
}

