}

/// Inner loop for yes/no prompt, separated to ensure cleanup runs on all exit paths.
fn prompt_yes_no_loop(
    term: &Term,
    options: &[PromptOption],
    sel: &mut usize,
    pad: &str,
    active_prefix: &Style,
    active_style: &Style,
    inactive_prefix: &Style,
    inactive_style: &Style,
    prompt: &Prompt,
) -> Result<PromptResult> {
    loop {
        // Draw option lines
        for (i, opt) in options.iter().enumerate() {
            let line = if i == *sel {
                format!(
                    "{}{} {}",
                    pad,
                    active_prefix.apply_to("›"),
                    active_style.apply_to(&opt.label)
                )
            } else {
                format!(
                    "{}{} {}",
                    pad,
                    inactive_prefix.apply_to("·"),
                    inactive_style.apply_to(&opt.label)
                )
            };
